//! Rendering of the generated TypeScript sources from the parsed schema model.

use std::collections::BTreeMap;

use anyhow::{bail, Result};
use preloop_gha_schema::{BuiltinType, Definition, Kind, Property, Schema, TypeRef};

use crate::naming;
use crate::GeneratedFile;

/// The schema files the generated output is derived from, named in every
/// header.
const SCHEMA_FILES: &str = "workflow-v1.0.json, action-v1.0.json";

/// The regeneration hint every generated file carries on its second line.
const HEADER_SECOND: &str = "// Regenerate with: cargo run -p loopt-sdkgen -- typescript";

/// The kit type import shared by `workflow.ts` and `action.ts`.
const KIT_IMPORT: &str = "import type { DocValue as KitDocValue, Expr as KitExpr, Scalar as KitScalar, Val as KitVal } from \"../kit/index.ts\";";

/// Names bound by [`KIT_IMPORT`]; a generated type may not shadow them.
const KIT_IMPORT_NAMES: [&str; 4] = ["KitDocValue", "KitExpr", "KitScalar", "KitVal"];

/// The fixed TypeScript declarations at the top of `model.ts`, before the two
/// embedded schema values.
const MODEL_DECLARATIONS: &str = r#"export type TypeRef = string;
export interface ContextSpec { name: string; min?: number; max?: number }
export interface Property { type: TypeRef; required?: true; description?: string }
export type Definition = {
  description?: string;
  contexts?: ContextSpec[];
} & (
  | { kind: "null" | "boolean" | "number" }
  | { kind: "string"; constant?: string; requireNonEmpty?: true }
  | { kind: "allowed-values"; values: string[] }
  | { kind: "sequence"; item: TypeRef }
  | { kind: "mapping"; properties: Record<string, Property>; looseKey?: TypeRef; looseValue?: TypeRef }
  | { kind: "one-of"; members: TypeRef[] }
);
export interface Schema { version?: string; definitions: Record<string, Definition> }
export const WORKFLOW_ROOT = "workflow-root-strict";
export const ACTION_ROOT = "action-root-strict";
"#;

/// Renders every generated file, in a stable order.
pub(crate) fn generate() -> Result<Vec<GeneratedFile>> {
    let workflow = preloop_gha_schema::workflow();
    let action = preloop_gha_schema::action();
    Ok(vec![
        GeneratedFile {
            path: "model.ts".to_owned(),
            content: render_model(workflow, action)?,
        },
        GeneratedFile {
            path: "aliases.ts".to_owned(),
            content: render_aliases(workflow, action)?,
        },
        GeneratedFile {
            path: "workflow.ts".to_owned(),
            content: render_types(workflow)?,
        },
        GeneratedFile {
            path: "action.ts".to_owned(),
            content: render_types(action)?,
        },
    ])
}

/// Returns the two-line generated-file header.
fn header() -> String {
    format!("// GENERATED by loopt-sdkgen from {SCHEMA_FILES} - do not edit.\n{HEADER_SECOND}\n")
}

/// Renders `model.ts` with both schemas embedded as JSON object literals.
fn render_model(workflow: &Schema, action: &Schema) -> Result<String> {
    let workflow_json = serde_json::to_string_pretty(&serde_json::to_value(workflow)?)?;
    let action_json = serde_json::to_string_pretty(&serde_json::to_value(action)?)?;

    let mut out = header();
    out.push_str(MODEL_DECLARATIONS);
    out.push_str("export const WORKFLOW_SCHEMA: Schema = ");
    out.push_str(&workflow_json);
    out.push_str(";\n");
    out.push_str("export const ACTION_SCHEMA: Schema = ");
    out.push_str(&action_json);
    out.push_str(";\n");
    Ok(out)
}

/// Renders `aliases.ts` with the camelCase-to-exact-key tables.
fn render_aliases(workflow: &Schema, action: &Schema) -> Result<String> {
    let workflow_aliases = serde_json::to_string_pretty(&aliases_value(workflow)?)?;
    let action_aliases = serde_json::to_string_pretty(&aliases_value(action)?)?;

    let mut out = header();
    out.push_str("export const WORKFLOW_ALIASES: Record<string, Record<string, string>> = ");
    out.push_str(&workflow_aliases);
    out.push_str(";\n\n");
    out.push_str("export const ACTION_ALIASES: Record<string, Record<string, string>> = ");
    out.push_str(&action_aliases);
    out.push_str(";\n");
    Ok(out)
}

/// Builds the alias table for one schema.
fn aliases_value(schema: &Schema) -> Result<serde_json::Value> {
    let mut definitions = serde_json::Map::new();
    for (name, definition) in &schema.definitions {
        if let Kind::Mapping { properties, .. } = &definition.kind {
            if properties.is_empty() {
                continue;
            }
            let entries: Vec<(&String, &Property)> = properties.iter().collect();
            let aliases = mapping_aliases(name.as_str(), &entries)?;
            let mut table = serde_json::Map::new();
            for (camel, key) in aliases {
                table.insert(camel, serde_json::Value::String(key));
            }
            definitions.insert(name.as_str().to_owned(), serde_json::Value::Object(table));
        }
    }
    Ok(serde_json::Value::Object(definitions))
}

/// Renders `workflow.ts` or `action.ts` for one schema.
fn render_types(schema: &Schema) -> Result<String> {
    let names = definition_names(schema)?;
    let mut declarations = Vec::with_capacity(names.len());
    for (name, pascal) in &names {
        let definition = schema
            .get(name.as_str())
            .expect("definition names come from the schema itself");
        declarations.push(render_definition(
            schema,
            name.as_str(),
            pascal.as_str(),
            definition,
        )?);
    }

    let mut out = header();
    out.push_str(KIT_IMPORT);
    out.push('\n');
    for declaration in declarations {
        out.push('\n');
        out.push_str(&declaration);
        out.push('\n');
    }
    Ok(out)
}

/// Validates and converts every definition name in schema order.
fn definition_names(schema: &Schema) -> Result<Vec<(String, String)>> {
    let mut names = Vec::with_capacity(schema.definitions.len());
    let mut seen: BTreeMap<String, String> = BTreeMap::new();
    for name in schema.definitions.keys() {
        let pascal = naming::pascal_case(name.as_str());
        if !naming::is_identifier(pascal.as_str()) {
            bail!(
                "definition `{name}` maps to `{pascal}`, which is not a valid TypeScript identifier"
            );
        }
        if KIT_IMPORT_NAMES.contains(&pascal.as_str()) {
            bail!("definition `{name}` maps to `{pascal}`, which clashes with a kit import");
        }
        if let Some(previous) = seen.insert(pascal.clone(), name.as_str().to_owned()) {
            bail!("definitions `{previous}` and `{name}` both map to `{pascal}`");
        }
        names.push((name.as_str().to_owned(), pascal));
    }
    Ok(names)
}

/// Renders one definition as a TypeScript declaration, preceded by its TSDoc
/// block when the schema carries a description.
fn render_definition(
    schema: &Schema,
    name: &str,
    pascal: &str,
    definition: &Definition,
) -> Result<String> {
    let expr_capable = !definition.contexts.is_empty();
    let mut out = String::new();
    if let Some(description) = &definition.description {
        out.push_str(&tsdoc_block(description));
        out.push('\n');
    }

    match &definition.kind {
        Kind::Null => out.push_str(&format!("export type {pascal} = null;")),
        Kind::Boolean => {
            let rendered = if expr_capable {
                "KitVal<boolean>"
            } else {
                "boolean"
            };
            out.push_str(&format!("export type {pascal} = {rendered};"));
        }
        Kind::Number => {
            let rendered = if expr_capable {
                "KitVal<number>"
            } else {
                "number"
            };
            out.push_str(&format!("export type {pascal} = {rendered};"));
        }
        Kind::String { constant, .. } => {
            let rendered = if expr_capable {
                if name.ends_with("-if") {
                    "KitExpr<boolean> | boolean".to_owned()
                } else {
                    "KitVal<string>".to_owned()
                }
            } else if let Some(value) = constant {
                ts_string(value.as_str())
            } else {
                "string".to_owned()
            };
            out.push_str(&format!("export type {pascal} = {rendered};"));
        }
        Kind::AllowedValues { values } => {
            if values.is_empty() {
                bail!("definition `{name}` declares no allowed values");
            }
            let rendered = values
                .iter()
                .map(|value| ts_string(value.as_str()))
                .collect::<Vec<_>>()
                .join(" | ");
            out.push_str(&format!("export type {pascal} = {rendered};"));
        }
        Kind::Sequence { item } => {
            let item = render_type_ref(schema, item, expr_capable)?;
            out.push_str(&format!("export type {pascal} = Array<{item}>;"));
        }
        Kind::OneOf { members } => {
            if members.is_empty() {
                bail!("definition `{name}` declares no one-of members");
            }
            let rendered = members
                .iter()
                .map(|member| render_type_ref(schema, member, expr_capable))
                .collect::<Result<Vec<_>>>()?
                .join(" | ");
            out.push_str(&format!("export type {pascal} = {rendered};"));
        }
        Kind::Mapping {
            properties,
            loose_value,
            ..
        } => {
            let entries: Vec<(&String, &Property)> = properties.iter().collect();
            out.push_str(&render_mapping(
                schema,
                name,
                pascal,
                &entries,
                loose_value.as_ref(),
                expr_capable,
            )?);
        }
    }

    Ok(out)
}

/// Renders a mapping definition as an interface (when it declares properties)
/// or as a `Record` alias.
fn render_mapping(
    schema: &Schema,
    definition: &str,
    pascal: &str,
    entries: &[(&String, &Property)],
    loose_value: Option<&TypeRef>,
    expr_capable: bool,
) -> Result<String> {
    if entries.is_empty() {
        return Ok(match loose_value {
            Some(ty) => {
                let value = if expr_capable && is_string_type(schema, ty) {
                    "KitVal<KitScalar>".to_owned()
                } else {
                    render_type_ref(schema, ty, expr_capable)?
                };
                format!("export type {pascal} = Record<string, {value}>;")
            }
            None => format!("export type {pascal} = Record<string, KitDocValue>;"),
        });
    }

    let aliases = mapping_aliases(definition, entries)?;
    let mut out = format!("export interface {pascal} {{\n");
    for ((camel, _key), entry) in aliases.iter().zip(entries) {
        let property = entry.1;
        if let Some(description) = property_description(schema, property) {
            out.push_str("  ");
            out.push_str(&tsdoc_line(description));
            out.push('\n');
        }
        let property_type = render_type_ref(schema, &property.ty, expr_capable)?;
        let property_name = if naming::is_identifier(camel.as_str()) {
            camel.as_str().to_owned()
        } else {
            ts_string(camel.as_str())
        };
        let optional = if property.required { "" } else { "?" };
        out.push_str(&format!("  {property_name}{optional}: {property_type};\n"));
    }
    out.push_str("  extra?: Record<string, KitDocValue>;\n");
    if loose_value.is_some() {
        out.push_str("  [key: string]: unknown;\n");
    }
    out.push('}');
    Ok(out)
}

/// Derives and validates the camelCase alias for every declared property.
fn mapping_aliases(
    definition: &str,
    entries: &[(&String, &Property)],
) -> Result<Vec<(String, String)>> {
    let mut aliases = Vec::with_capacity(entries.len());
    let mut seen: BTreeMap<String, String> = BTreeMap::new();
    for &(key, _property) in entries {
        let camel = naming::camel_case(key.as_str());
        if camel == "extra" {
            bail!(
                "definition `{definition}` property `{key}` maps to `extra`, which is reserved for extra properties"
            );
        }
        if let Some(previous) = seen.insert(camel.clone(), key.as_str().to_owned()) {
            bail!(
                "definition `{definition}` properties `{previous}` and `{key}` both map to `{camel}`"
            );
        }
        aliases.push((camel, key.as_str().to_owned()));
    }
    Ok(aliases)
}

/// Renders a single type reference, wrapping expression-capable primitives in
/// `KitVal` when the surrounding definition accepts expressions.
fn render_type_ref(schema: &Schema, ty: &TypeRef, expr_capable: bool) -> Result<String> {
    let base = match ty {
        TypeRef::Builtin(builtin) => match builtin {
            BuiltinType::Null => "null".to_owned(),
            BuiltinType::Boolean => "boolean".to_owned(),
            BuiltinType::Number => "number".to_owned(),
            BuiltinType::String => "string".to_owned(),
            BuiltinType::Sequence => "Array<KitDocValue>".to_owned(),
            BuiltinType::Mapping => "Record<string, KitDocValue>".to_owned(),
            BuiltinType::Any => "KitDocValue".to_owned(),
        },
        TypeRef::Definition(name) => {
            if schema.get(name.as_str()).is_none() {
                bail!("type reference `{name}` does not resolve to a definition");
            }
            naming::pascal_case(name.as_str())
        }
    };

    if expr_capable && is_expression_primitive(schema, ty) {
        Ok(format!("KitVal<{base}>"))
    } else {
        Ok(base)
    }
}

/// Whether a reference names a primitive that can carry an expression.
fn is_expression_primitive(schema: &Schema, ty: &TypeRef) -> bool {
    match ty {
        TypeRef::Builtin(BuiltinType::Boolean)
        | TypeRef::Builtin(BuiltinType::Number)
        | TypeRef::Builtin(BuiltinType::String) => true,
        TypeRef::Builtin(_) => false,
        TypeRef::Definition(name) => match schema.get(name.as_str()) {
            Some(definition) => matches!(
                &definition.kind,
                Kind::Boolean | Kind::Number | Kind::String { constant: None, .. }
            ),
            None => false,
        },
    }
}

/// Whether a reference names a string: the builtin, or a string-kind
/// definition that does not pin a constant.
fn is_string_type(schema: &Schema, ty: &TypeRef) -> bool {
    match ty {
        TypeRef::Builtin(BuiltinType::String) => true,
        TypeRef::Builtin(_) => false,
        TypeRef::Definition(name) => match schema.get(name.as_str()) {
            Some(definition) => matches!(&definition.kind, Kind::String { constant: None, .. }),
            None => false,
        },
    }
}

/// Returns the description a property should document itself with: its own
/// description, otherwise the referenced definition's description.
fn property_description<'a>(schema: &'a Schema, property: &'a Property) -> Option<&'a str> {
    if let Some(description) = property
        .description
        .as_deref()
        .filter(|description| !description.trim().is_empty())
    {
        return Some(description);
    }
    property
        .ty
        .as_definition()
        .and_then(|name| schema.get(name))
        .and_then(|definition| definition.description.as_deref())
        .filter(|description| !description.trim().is_empty())
}

/// Renders a definition description as a TSDoc block. Comment terminators are
/// escaped so the description can never close the block early.
fn tsdoc_block(description: &str) -> String {
    let mut out = String::from("/**");
    for line in description.lines() {
        out.push('\n');
        let escaped = escape_comment_terminator(line);
        if escaped.is_empty() {
            out.push_str(" *");
        } else {
            out.push_str(" * ");
            out.push_str(&escaped);
        }
    }
    out.push('\n');
    out.push_str(" */");
    out
}

/// Renders a property description as a single-line TSDoc comment.
fn tsdoc_line(description: &str) -> String {
    format!(
        "/** {} */",
        escape_comment_terminator(&single_line(description))
    )
}

/// Joins every line of `text` into one space-separated line.
fn single_line(text: &str) -> String {
    text.split('\n')
        .map(|line| line.strip_suffix('\r').unwrap_or(line))
        .collect::<Vec<_>>()
        .join(" ")
        .trim()
        .to_owned()
}

/// Escapes `*/` so it cannot terminate the surrounding block comment.
fn escape_comment_terminator(text: &str) -> String {
    text.replace("*/", "*\\/")
}

/// Renders `value` as a double-quoted TypeScript string literal.
fn ts_string(value: &str) -> String {
    serde_json::to_string(value).expect("serializing a string to JSON cannot fail")
}
